 {tab==='polls'&&<><div className="toolbar"><p>Escolha o MVP, a escalação ou o próximo treino. Um voto por navegador.</p>{admin&&<button className="button primary" onClick={()=>editRecord('poll','Nova votação',[{key:'name',label:'Pergunta',required:true},{key:'choices',label:'Opções (uma por linha)',type:'textarea',required:true},{key:'endsAt',label:'Encerramento',type:'datetime-local'}],undefined,v=>({...v,options:v.choices.split('\n').map((s:string)=>s.trim()).filter(Boolean)}))}><Plus size={16}/>Votação</button>}</div><div className="card-grid">{byKind('poll').map(r=><article className="poll-card" key={r.id}><Vote/><h3>{r.data.name}</h3>{r.data.options?.map((option:string)=>{const votes=data.votes.find(v=>v.pollId===r.id&&v.choice===option)?.count??0;return <button key={option} disabled={r.data.closed||(r.data.endsAt&&Date.parse(r.data.endsAt)<now)} onClick={async()=>{try{let id=localStorage.getItem('touchline-voter');if(!id){id=crypto.randomUUID();localStorage.setItem('touchline-voter',id)}await api('vote',{pollId:r.id,choice:option,voter:id});await refresh();setNotice('Voto registrado.')}catch(e){setNotice((e as Error).message)}}}><span>{option}</span><b>{votes}</b></button>})}<small>{r.data.endsAt?`Encerra ${dayTime(r.data.endsAt)}`:'Votação aberta'}</small>{actions(r)}</article>)}</div>{!byKind('poll').length&&<Empty title="A equipe também decide" text="Um diretor pode abrir uma votação com as opções e o prazo."/>}</>}
